class Solution:
    def mincostToHireWorkers(self, quality: list[int], wage: list[int], k: int) -> float:
        n = len(quality)
        best = float('inf')
        for i in range(n):
            rate = wage[i] / quality[i]
            eligible = []
            for q, w in zip(quality, wage):
                if w / q <= rate:
                    eligible.append(q)
            if len(eligible) >= k:
                eligible.sort()
                best = min(best, sum(eligible[:k]) * rate)
        return round(best, 5)

