class Solution:
    def mincostToHireWorkers(self, quality, wage, k):
        import heapq
        workers = sorted((w / q, q) for q, w in zip(quality, wage))
        heap = []
        total_q = 0
        best = float('inf')
        for rate, q in workers:
            heapq.heappush(heap, -q)
            total_q += q
            if len(heap) > k:
                total_q += heapq.heappop(heap)
            if len(heap) == k:
                best = min(best, total_q * rate)
        return round(best, 5)

